{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.sku_wise_Inward_planning AS WITH base AS ( SELECT UPPER(TRIM(cleaned_sku)) AS sku_group, TRY_TO_NUMBER( REPLACE(TRIM(qty), \',\', \'\') ) AS qty, CASE WHEN remarks_final ILIKE \'JAN%\' THEN 1 WHEN remarks_final ILIKE \'FEB%\' THEN 2 WHEN remarks_final ILIKE \'MAR%\' THEN 3 WHEN remarks_final ILIKE \'APR%\' THEN 4 WHEN remarks_final ILIKE \'MAY%\' THEN 5 WHEN remarks_final ILIKE \'JUN%\' THEN 6 WHEN remarks_final ILIKE \'JUL%\' THEN 7 WHEN remarks_final ILIKE \'AUG%\' THEN 8 WHEN remarks_final ILIKE \'SEP%\' THEN 9 WHEN remarks_final ILIKE \'OCT%\' THEN 10 WHEN remarks_final ILIKE \'NOV%\' THEN 11 WHEN remarks_final ILIKE \'DEC%\' THEN 12 ELSE NULL END AS planned_month FROM snitch_db.maplemonk.inwards_list_mom_v2_sku_list_with_month_remarks ), base_unique AS ( SELECT sku_group, planned_month, qty FROM base WHERE planned_month > 4 QUALIFY ROW_NUMBER() OVER ( PARTITION BY sku_group, planned_month ORDER BY sku_group ) = 1 ), base_ranked AS ( SELECT sku_group, planned_month, qty, ROW_NUMBER() OVER ( PARTITION BY sku_group ORDER BY planned_month ASC ) AS rn FROM base_unique ), inward AS ( SELECT UPPER( TRIM( REGEXP_REPLACE( \"Item Type skuCode\", \'-[0-9A-Za-z]{1,5}$\', \'\' ) ) ) AS sku_group, MONTH(putaway_completed_date) AS inward_month, SUM( TRY_TO_NUMBER(putaway_completed_quantity) ) AS inwarded_qty FROM snitch_db.maplemonk.putaway_tracking WHERE final_type ILIKE \'New inward\' AND \"Putaway Item Status Code\" ILIKE \'complete\' AND is_trading ILIKE \'True\' AND MONTH(putaway_completed_date) > 4 GROUP BY 1, 2 having inwarded_qty > 100 ), inward_ranked AS ( SELECT sku_group, inward_month, inwarded_qty, ROW_NUMBER() OVER ( PARTITION BY sku_group ORDER BY inward_month ASC ) AS rn FROM inward ), matched AS ( SELECT b.sku_group, b.planned_month, b.qty AS planned_qty, b.rn AS planned_rank, i.inward_month, i.inwarded_qty, i.rn AS inward_rank FROM base_ranked b LEFT JOIN inward_ranked i ON i.sku_group = b.sku_group AND i.rn = b.rn ) SELECT sku_group, planned_month, CASE WHEN planned_month = 1 THEN \'JANUARY\' WHEN planned_month = 2 THEN \'FEBRUARY\' WHEN planned_month = 3 THEN \'MARCH\' WHEN planned_month = 4 THEN \'APRIL\' WHEN planned_month = 5 THEN \'MAY\' WHEN planned_month = 6 THEN \'JUNE\' WHEN planned_month = 7 THEN \'JULY\' WHEN planned_month = 8 THEN \'AUGUST\' WHEN planned_month = 9 THEN \'SEPTEMBER\' WHEN planned_month = 10 THEN \'OCTOBER\' WHEN planned_month = 11 THEN \'NOVEMBER\' WHEN planned_month = 12 THEN \'DECEMBER\' END AS planned_month_name, planned_qty, inward_month, CASE WHEN inward_month = 1 THEN \'JANUARY\' WHEN inward_month = 2 THEN \'FEBRUARY\' WHEN inward_month = 3 THEN \'MARCH\' WHEN inward_month = 4 THEN \'APRIL\' WHEN inward_month = 5 THEN \'MAY\' WHEN inward_month = 6 THEN \'JUNE\' WHEN inward_month = 7 THEN \'JULY\' WHEN inward_month = 8 THEN \'AUGUST\' WHEN inward_month = 9 THEN \'SEPTEMBER\' WHEN inward_month = 10 THEN \'OCTOBER\' WHEN inward_month = 11 THEN \'NOVEMBER\' WHEN inward_month = 12 THEN \'DECEMBER\' END AS inward_month_name, inwarded_qty, CASE WHEN inward_month IS NULL THEN \'PENDING\' ELSE \'INWARDED\' END AS inward_status, CASE WHEN inward_month IS NULL THEN NULL ELSE inward_month - planned_month END AS month_deviation, planned_rank, inward_rank FROM matched ORDER BY sku_group, planned_month;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

